import { type KeyboardEvent, type MouseEvent } from 'react';
import { type ImmutableObject } from 'seamless-immutable';
import { type ModalStates } from '@types/divi__modal';
import { type CloudApp, type ModuleFlatObject, type ModuleLibrary } from '@divi/types';
export type OnCloudUseItemData = ImmutableObject<CloudApp.Library.Item.Layout>;
export type OnCloudUseItem = (data: OnCloudUseItemData) => void;
export type ContainerProps = Omit<ModalStates, 'expand' | 'centered'>;
export interface OnFilterOptionChangeValue {
    inputValue: string;
}
export interface SelectedOption {
    name: string;
    position?: string;
}
export interface OnOptionKeyDownEvent {
    key: string;
}
export interface ShortcutsArgs {
    onOptionKeyDown: (event: KeyboardEvent<HTMLInputElement> | OnOptionKeyDownEvent) => void;
    onSwitchTab: () => void;
}
export interface Props extends ContainerProps {
    moduleFolderList: ModuleLibrary.ModuleFolder.Collections;
    moduleFolder: string;
    moduleFilter: string;
    parentModule: ModuleFlatObject;
    selectedOption: SelectedOption;
    type: 'specialty-section' | 'section' | 'row' | 'row-inner' | 'module';
    onButtonClick: (event: MouseEvent) => void;
    onBackButtonClick: (event: MouseEvent) => void;
    onFilterOptionChange: (value: OnFilterOptionChangeValue) => void;
    onOptionKeyDown: (event: KeyboardEvent<HTMLInputElement> | OnOptionKeyDownEvent) => void;
    onOptionMouseEnter?: (event: MouseEvent) => void;
    onOptionMouseLeave?: (event: MouseEvent) => void;
    adminBarHeight: number;
    topWindowHeight: number;
    topWindowWidth: number;
    openTab: (tabName: string) => void;
    onCloudUseItem: OnCloudUseItem;
    userCanAddFromLibrary: boolean;
}
